package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator.IdKey;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.deser.impl.DeserializerFactory;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.ser.impl.ObjectIdGenerator;
import com.fasterxml.jackson.databind.ser.impl.ObjectIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map.Entry;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DefaultDeserializationContext_findObjectId_TriageGen1Test {

    private DeserializerFactory deserializerFactory;
    private DeserializationConfig deserializationConfig;
    private JsonParser jsonParser;
    private InjectableValues injectableValues;
    private DefaultDeserializationContext context;

    @Before
    public void setUp() {
        deserializerFactory = mock(DeserializerFactory.class);
        deserializationConfig = mock(DeserializationConfig.class);
        jsonParser = mock(JsonParser.class);
        injectableValues = mock(InjectableValues.class);

        // Using the protected constructor via a subclass or mock-friendly approach
        // Since we cannot easily instantiate the abstract-like protected context without more dependencies,
        // we use the most accessible constructor pattern.
        context = new DefaultDeserializationContext(deserializerFactory, deserializationConfig, jsonParser, injectableValues) {
            // Concrete implementation for testing purposes if needed, 
            // but DefaultDeserializationContext is a concrete class in Jackson.
        };
    }

    @Test
    public void testFindObjectId_NewEntryAndNewResolver() throws Exception {
        Object id = "id1";
        ObjectIdGenerator<?> gen = mock(ObjectIdGenerator.class);
        ObjectIdResolver resolverType = mock(ObjectIdResolver.class);
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);
        ObjectIdResolver newResolver = mock(ObjectIdResolver.class);

        when(gen.key(id)).thenReturn(key);
        when(resolverType.newForDeserialization(any())).thenReturn(newResolver);

        // Act
        ReadableObjectId result = context.findObjectId(id, gen, resolverType);

        // Assert
        assertNotNull(result);
        assertEquals(key, result.getObjectId());

        // Verify internal state via reflection to ensure resolver was added to _objectIdResolvers
        List<ObjectIdResolver> resolvers = getInternalField("_objectIdResolvers");
        assertTrue(resolvers.contains(newResolver));

        // Verify internal state _objectIds
        Map<ObjectIdGenerator.IdKey, ReadableObjectId> objectIds = getInternalField("_objectIds");
        assertEquals(result, objectIds.get(key));
    }

    @Test
    public void testFindObjectId_ExistingEntryReturnsSame() throws Exception {
        Object id = "id1";
        ObjectIdGenerator<?> gen = mock(ObjectIdGenerator.class);
        ObjectIdResolver resolverType = mock(ObjectIdResolver.class);
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);

        when(gen.key(id)).thenReturn(key);
        when(resolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        // First call
        ReadableObjectId firstResult = context.findObjectId(id, gen, resolverType);
        // Second call
        ReadableObjectId secondResult = context.findObjectId(id, gen, resolverType);

        assertSame("Should return the same instance for the same key", firstResult, secondResult);
    }

    @Test
    public void testFindObjectId_ReuseExistingResolver() throws Exception {
        Object id1 = "id1";
        Object id2 = "id2";
        ObjectIdGenerator<?> gen = mock(ObjectIdGenerator.class);
        ObjectIdResolver resolverType = mock(ObjectIdResolver.class);
        ObjectIdGenerator.IdKey key1 = mock(ObjectIdGenerator.IdKey.class);
        ObjectIdGenerator.IdKey key2 = mock(ObjectIdGenerator.IdKey.class);

        ObjectIdResolver existingResolver = mock(ObjectIdResolver.class);

        when(gen.key(id1)).thenReturn(key1);
        when(gen.key(id2)).thenReturn(key2);
        when(resolverType.newForDeserialization(any())).thenReturn(existingResolver);

        // Setup existing resolver to be compatible with the requested type
        when(existingResolver.canUseFor(resolverType)).thenReturn(true);

        // First call creates the resolver
        context.findObjectId(id1, gen, resolverType);

        // Second call with different ID but same resolver type should reuse existing resolver
        ReadableObjectId secondResult = context.findObjectId(id2, gen, resolverType);

        // Check if the second entry uses the same resolver
        // We need to access the resolver via reflection or check if it's the same instance
        // Since ReadableObjectId doesn't have a public getResolver, we rely on the logic flow
        // and verify that newForDeserialization was only called once.
        verify(resolverType, times(1)).newForDeserialization(any());
    }

    @Test
    public void testFindObjectId_NullId() throws Exception {
        // Test the requirement: "should allow 'null'"
        Object id = null;
        ObjectIdGenerator<?> gen = mock(ObjectIdGenerator.class);
        ObjectIdResolver resolverType = mock(ObjectIdResolver.class);
        ObjectIdGenerator.IdKey key = mock(ObjectIdGenerator.IdKey.class);

        when(gen.key(null)).thenReturn(key);
        when(resolverType.newForDeserialization(any())).thenReturn(mock(ObjectIdResolver.class));

        ReadableObjectId result = context.findObjectId(id, gen, resolverType);
        assertNotNull(result);
        assertEquals(key, result.getObjectId());
    }

    @Test
    public void testFindObjectId_ResolverNotCompatible() throws Exception {
        Object id1 = "id1";
        Object id2 = "id2";
        ObjectIdGenerator<?> gen = mock(ObjectIdGenerator.class);
        ObjectIdResolver resolverType = mock(ObjectIdResolver.class);
        ObjectIdGenerator.IdKey key1 = mock(ObjectIdGenerator.IdKey.class);
        ObjectIdGenerator.IdKey key2 = mock(ObjectIdGenerator.IdKey.class);

        ObjectIdResolver existingResolver = mock(ObjectIdResolver.class);

        when(gen.key(id1)).thenReturn(key1);
        when(gen.key(id2)).thenReturn(key2);
        when(resolverType.newForDeserialization(any())).thenReturn(existingResolver);

        // First resolver cannot use the requested type
        when(existingResolver.canUseFor(resolverType)).thenReturn(false);

        // First call
        context.findObjectId(id1, gen, resolverType);

        // Second call: since existingResolver.canUseFor returns false, it should create a new one
        context.findObjectId(id2, gen, resolverType);

        // Verify newForDeserialization was called twice because the first one wasn't compatible
        verify(resolverType, times(2)).newForDeserialization(any());
    }

    @SuppressWarnings("unchecked")
    private <T> T getInternalField(String fieldName) throws Exception {
        Field field = DefaultDeserializationContext.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return (T) field.get(context);
    }
}
